199	          "metadataOperationLatency" + interval + "s",
200	          "Metadata Operation Latency in ms", "ops", "latency", interval);
201	      dataFileIoLatencyQuantiles[i] = registry.newQuantiles(
202	          "dataFileIoLatency" + interval + "s",
203	          "Data File Io Latency in ms", "ops", "latency", interval);
204	      flushIoLatencyQuantiles[i] = registry.newQuantiles(
205	          "flushIoLatency" + interval + "s",
206	          "Data flush Io Latency in ms", "ops", "latency", interval);
207	      syncIoLatencyQuantiles[i] = registry.newQuantiles(
208	          "syncIoLatency" + interval + "s",
209	          "Data sync Io Latency in ms", "ops", "latency", interval);
210	      readIoLatencyQuantiles[i] = registry.newQuantiles(
211	          "readIoLatency" + interval + "s",
212	          "Data read Io Latency in ms", "ops", "latency", interval);
213	      writeIoLatencyQuantiles[i] = registry.newQuantiles(
214	          "writeIoLatency" + interval + "s",
215	          "Data write Io Latency in ms", "ops", "latency", interval);
216	    }
217	  }
