32	import java.util.concurrent.ThreadLocalRandom;
33	
34	/**
35	 * Profiles the performance of the metadata and data related operations on
36	 * datanode volumes.
37	 */
38	@InterfaceAudience.Private
39	class ProfilingFileIoEvents {
40	  static final Logger LOG =
41	      LoggerFactory.getLogger(ProfilingFileIoEvents.class);
42	
43	  private final boolean isEnabled;
44	  private final int sampleRangeMax;
45	
46	  public ProfilingFileIoEvents(@Nullable Configuration conf) {
47	    if (conf != null) {
48	      int fileIOSamplingPercentage = conf.getInt(
49	          DFSConfigKeys.DFS_DATANODE_FILEIO_PROFILING_SAMPLING_PERCENTAGE_KEY,
50	          DFSConfigKeys
51	              .DFS_DATANODE_FILEIO_PROFILING_SAMPLING_PERCENTAGE_DEFAULT);
52	      isEnabled = Util.isDiskStatsEnabled(fileIOSamplingPercentage);
53	      if (fileIOSamplingPercentage > 100) {
54	        LOG.warn(DFSConfigKeys
55	            .DFS_DATANODE_FILEIO_PROFILING_SAMPLING_PERCENTAGE_KEY +
56	            " value cannot be more than 100. Setting value to 100");
57	        fileIOSamplingPercentage = 100;
58	      }
59	      sampleRangeMax = (int) ((double) fileIOSamplingPercentage / 100 *
60	          Integer.MAX_VALUE);
61	    } else {
62	      isEnabled = false;
63	      sampleRangeMax = 0;
64	    }
65	  }
66	
67	  public long beforeMetadataOp(@Nullable FsVolumeSpi volume,
68	      FileIoProvider.OPERATION op) {
69	    if (isEnabled) {
70	      DataNodeVolumeMetrics metrics = getVolumeMetrics(volume);
71	      if (metrics != null) {
72	        return Time.monotonicNow();
73	      }
74	    }
75	    return 0;
76	  }
77	
78	  public void afterMetadataOp(@Nullable FsVolumeSpi volume,
79	      FileIoProvider.OPERATION op, long begin) {
80	    if (isEnabled) {
81	      DataNodeVolumeMetrics metrics = getVolumeMetrics(volume);
82	      if (metrics != null) {
83	        metrics.addMetadataOperationLatency(Time.monotonicNow() - begin);
84	      }
85	    }
86	  }
87	
88	  public long beforeFileIo(@Nullable FsVolumeSpi volume,
89	      FileIoProvider.OPERATION op, long len) {
90	    if (isEnabled && ThreadLocalRandom.current().nextInt() < sampleRangeMax) {
91	      DataNodeVolumeMetrics metrics = getVolumeMetrics(volume);
92	      if (metrics != null) {
93	        return Time.monotonicNow();
94	      }
95	    }
96	    return 0;
97	  }
98	
99	  public void afterFileIo(@Nullable FsVolumeSpi volume,
100	      FileIoProvider.OPERATION op, long begin, long len) {
101	    if (isEnabled && begin != 0) {
102	      DataNodeVolumeMetrics metrics = getVolumeMetrics(volume);
103	      if (metrics != null) {
104	        long latency = Time.monotonicNow() - begin;
105	        metrics.addDataFileIoLatency(latency);
106	        switch (op) {
107	        case SYNC:
108	          metrics.addSyncIoLatency(latency);
109	          break;
110	        case FLUSH:
111	          metrics.addFlushIoLatency(latency);
112	          break;
113	        case READ:
114	          metrics.addReadIoLatency(latency);
115	          break;
116	        case WRITE:
117	          metrics.addWriteIoLatency(latency);
118	          break;
119	        default:
120	        }
121	      }
122	    }
123	  }
124	
125	  public void onFailure(@Nullable FsVolumeSpi volume, long begin) {
126	    if (isEnabled) {
127	      DataNodeVolumeMetrics metrics = getVolumeMetrics(volume);
128	      if (metrics != null) {
129	        metrics.addFileIoError(Time.monotonicNow() - begin);
130	      }
131	    }
132	  }
133	
134	  private DataNodeVolumeMetrics getVolumeMetrics(final FsVolumeSpi volume) {
135	    if (isEnabled) {
136	      if (volume != null) {
137	        return volume.getMetrics();
138	      }
139	    }
140	    return null;
141	  }
142	}
